import java.util.Map;
import java.util.Set;

public class LowCodeRuntime {
    private final MetadataCache metadataCache;
    private final ComponentRegistry componentRegistry;
    private final PermissionEngine permissionEngine;
    private final WorkflowEngine workflowEngine;
    private final DynamicDataService dynamicDataService;
    private final ScriptSandbox scriptSandbox;

    public RenderResult renderPage(RuntimeContext ctx, String pageId) {
        // 按租户、应用、页面和版本读取不可变快照，避免设计器草稿污染线上页面
        RuntimeSnapshot snapshot = metadataCache.get(ctx.tenantId(), ctx.appId(), pageId, ctx.version());
        // 权限引擎先计算当前用户命中的 RBAC 和 ABAC 规则
        PermissionView permissionView = permissionEngine.evaluate(ctx.user(), snapshot.permissionMeta());
        // 组件树在服务端完成按钮、字段和区域级裁剪，不能只依赖前端隐藏
        PageMeta filteredPage = permissionEngine.filterComponentTree(snapshot.pageMeta(), permissionView);
        return componentRegistry.render(filteredPage, ctx, dynamicDataService);
    }

    public ActionResult executeAction(RuntimeContext ctx, ActionMeta action, Map<String, Object> payload) {
        // 动作执行前再次校验资源和动作权限，防止用户绕过页面直接调用接口
        permissionEngine.checkAction(ctx.user(), action.resourceCode(), action.actionCode());
        if (action.type() == ActionType.START_WORKFLOW) {
            // 审批流作为低代码动作的一种进入流程引擎
            return workflowEngine.start(ctx, action.workflowKey(), payload);
        }
        if (action.type() == ActionType.SAVE_ENTITY) {
            EntityMeta entityMeta = metadataCache.getEntity(ctx.tenantId(), action.entityName(), ctx.version());
            // 保存动态实体前按 EntityMeta 做字段类型和必填校验
            dynamicDataService.validate(entityMeta, payload);
            // 数据服务写入时注入租户和数据范围
            dynamicDataService.saveWithDataScope(ctx, entityMeta, payload);
            return ActionResult.success();
        }
        if (action.type() == ActionType.RUN_SCRIPT) {
            // 自定义脚本通过沙箱执行并限制超时，防止插件拖垮运行时线程
            return scriptSandbox.run(ctx, action.scriptId(), payload, 3000);
        }
        throw new UnsupportedOperationException("unsupported low-code action: " + action.type());
    }
}

interface MetadataCache {
    RuntimeSnapshot get(String tenantId, String appId, String pageId, String version);
    EntityMeta getEntity(String tenantId, String entityName, String version);
}

interface PermissionEngine {
    PermissionView evaluate(UserPrincipal user, PermissionMeta permissionMeta);
    PageMeta filterComponentTree(PageMeta pageMeta, PermissionView permissionView);
    void checkAction(UserPrincipal user, String resourceCode, String actionCode);
}

interface DynamicDataService {
    void validate(EntityMeta entityMeta, Map<String, Object> payload);
    void saveWithDataScope(RuntimeContext ctx, EntityMeta entityMeta, Map<String, Object> payload);
}

record RuntimeContext(String tenantId, String appId, String version, UserPrincipal user) {}
record RuntimeSnapshot(PageMeta pageMeta, PermissionMeta permissionMeta) {}
record PageMeta(String pageId, Set<ComponentMeta> components) {}
record ComponentMeta(String type, Map<String, Object> props) {}
record EntityMeta(String name, Map<String, String> fields) {}
record ActionMeta(ActionType type, String resourceCode, String actionCode, String workflowKey, String entityName, String scriptId) {}
record PermissionMeta(Map<String, Object> rules) {}
record PermissionView(Set<String> resources, Map<String, Object> dataScopes) {}
record UserPrincipal(String userId, Set<String> roles) {}
record RenderResult(String html) {}
record ActionResult(boolean success) { static ActionResult success() { return new ActionResult(true); } }
enum ActionType { START_WORKFLOW, SAVE_ENTITY, RUN_SCRIPT }
